/// <summary>
/// DebuC 22.09.23
/// last modified: PaffH 28.05.25
/// </summary>
[DataContractAttribute,
    SysOperationContractProcessing(classStr(NDXUmsatzCSRefreshUIBuilder))]
class NDXUmsatzCSRefreshContract
{
    NDXUmsatzCSRefreshType      umsatzCSRefreshType;
    NoYes                       lThread;
    boolean                     lBuildAlliance;
    boolean                     lBuildSalesGroup;
    NoYes                       lBuildVerband;
    NoYes                       lBuildAll;
    NoYes                       lLiveSales;
    NoYes                       lfillKumUmsCust;
    NoYes                       lCheckKumUmsCust;
    CustAccount                 alliance;
    CommissSalesGroup           salesGroup;
    Version                     dataVersion;
    NDXMonthBE                  liveSalesMonth;
    NDXYear                     liveSalesYear;
    NDXBatchWithMultithreading batchWithMultithreading;

}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_umsatzCSRefreshType">NDXUmsatzCSRefreshType</param>
/// <returns>NDXUmsatzCSRefreshType</returns>
[DataMember,
        SysOperationLabel(literalStr("Typ")),
        SysOperationHelpText(literalStr("Typ der Aufbereitung")),
        SysOperationDisplayOrder('1')]
    public NDXUmsatzCSRefreshType parmumsatzCSRefreshType(NDXUmsatzCSRefreshType _umsatzCSRefreshType = umsatzCSRefreshType)
{
    umsatzCSRefreshType = _umsatzCSRefreshType;

    if(umsatzCSRefreshType ==NDXUmsatzCSRefreshType::Alliance)
    {
        this.parmLBuildVerband(NoYes::Yes);
    }

    return umsatzCSRefreshType;
}

[DataMember,
        SysOperationLabel(literalStr("Verkaufsgruppe")),
        SysOperationHelpText(literalStr("Verkaufsgruppe der Aufbereitung")),
        SysOperationDisplayOrder('3')]
public CommissSalesGroup parmSalesGroup(CommissSalesGroup l_salesGroup = salesGroup)
{
    ;
    if (!prmisdefault(l_salesGroup))
    {
        this.parmLBuildSalesGroup(l_salesGroup > '');
    }

    salesGroup = l_salesGroup;
    return salesGroup;
}

boolean parmLBuildSalesGroup(boolean l_lBuildSalesGroup = lBuildSalesGroup)
{
    ;
    lBuildSalesGroup    = l_lBuildSalesGroup;
    lBuildAlliance      = !lBuildSalesGroup;
    return lBuildSalesGroup;
}

[DataMember,
        SysOperationLabel(literalStr("Datenversion")),
        SysOperationHelpText(literalStr("Datenversion der Aufbereitung")),
        SysOperationDisplayOrder('2')]
version parmDataVersion(Version l_dataVersion = dataVersion)
{
    dataVersion = l_dataVersion;
    return dataVersion;
}

[DataMember,
        SysOperationLabel(literalStr("Verband")),
        SysOperationHelpText(literalStr("Verband der Aufbereitung")),
        SysOperationDisplayOrder('4')]
CustAccount parmAlliance(CustAccount l_alliance = alliance)
{
    ;
    if (!prmisdefault(l_alliance))
    {
        this.parmLBuildAlliance(l_alliance > '');
    }

    alliance = l_alliance;
    return alliance;
}

/// <summary>
/// PaffH 20.01.25
/// </summary>
/// <param name = "_batchWithMultithreading">NDXBatchWithMultithreading</param>
/// <returns>batchWithMultithreading</returns>
[DataMember,
        SysOperationLabel(literalStr("Batch-Multithreading")),
        SysOperationHelpText(literalStr("Daten über Batch-Multithreading aufbereiten")),
        SysOperationDisplayOrder('5')]
NDXBatchWithMultithreading parmBatchWithMultithreading(NDXBatchWithMultithreading _batchWithMultithreading = batchWithMultithreading)
{
    batchWithMultithreading = _batchWithMultithreading;
    return batchWithMultithreading;
}

boolean parmLBuildAlliance(boolean l_lBuildAlliance = lBuildAlliance)
{
    ;
    lBuildAlliance      = l_lBuildAlliance;
    lBuildSalesGroup    = !lBuildAlliance;
    return lBuildAlliance;
}

NoYes parmLBuildVerband(NoYes l_lBuildVerband = lBuildVerband)
{
    ;
    lBuildVerband   = l_lBuildVerband;
    return lBuildVerband;
}
